"""One deterministic post-ADC noise realization per burst/condition."""

from __future__ import annotations

import numpy as np

from .config import Noise


def markov_mask(n, seed, probability=0.01, mean_bad=3.0):
    """Stationary two-state process generated by geometric run lengths."""
    p10 = 1 / mean_bad
    p01 = probability * p10 / (1 - probability)
    if n < 1 or not 0 < p01 <= 1 or not 0 < p10 <= 1:
        raise ValueError("Unrealizable Markov parameters")
    rng = np.random.default_rng(seed)
    mask = np.zeros(n, bool)
    state, start = int(rng.random() < probability), 0
    while start < n:
        stop = min(n, start + int(rng.geometric(p10 if state else p01)))
        mask[start:stop] = bool(state)
        start, state = stop, 1 - state
    return mask


def generate(n: int, model: Noise, seed: int, signal_power: float):
    """Match realized added power; retain ambient noise and analog distortions.

    This finite-sample normalization is part of the experimental noise model.
    It does not estimate RF SNR, Eb/N0, propagation, ADC clipping or interference.
    """
    if n < 64 or not np.isfinite(signal_power) or signal_power <= 0:
        raise ValueError("Invalid sample count or activity power")
    if model.name == "natural":
        return np.zeros(n, np.complex64), {"model": "natural", "added_power": 0.0}
    target = signal_power * 10 ** (-model.snr_db / 10)
    rng = np.random.default_rng(seed)
    noise = (
        rng.standard_normal(n).astype("f4") + 1j * rng.standard_normal(n).astype("f4")
    ).astype("c8")
    noise *= np.float32(np.sqrt(target / 2))
    mask = np.zeros(n, bool)
    if model.name != "awgn":
        p, ratio = model.probability, model.variance_ratio
        mask = (
            rng.random(n) < p
            if model.name == "bernoulli_gaussian"
            else markov_mask(n, seed + 9797, p, model.mean_bad_samples)
        )
        noise *= np.float32((1 + p * (ratio - 1)) ** -0.5)
        count = int(mask.sum())
        extra = (
            rng.standard_normal(count).astype("f4")
            + 1j * rng.standard_normal(count).astype("f4")
        ).astype("c8")
        extra *= np.float32(np.sqrt(target * (ratio - 1) / (2 * (1 + p * (ratio - 1)))))
        noise[mask] += extra
    power = float(np.mean(abs(noise.astype("c16")) ** 2))
    noise *= np.float32(np.sqrt(target / power))
    realized = float(np.mean(abs(noise.astype("c16")) ** 2))
    return noise, dict(
        model=model.name,
        seed=seed,
        added_snr_db=model.snr_db,
        power_reference=signal_power,
        target_added_power=target,
        added_power=realized,
        bad_state_fraction=float(mask.mean()),
        probability=model.probability,
        variance_ratio=model.variance_ratio,
        mean_bad_samples=model.mean_bad_samples,
        scope="Digital noise after ADC and fixed DC removal, before synchronization",
    )
